    16→package com.google.auto.service.processor;
    17→
    18→import static com.google.common.base.Charsets.UTF_8;
    19→
    20→import java.io.BufferedReader;
    21→import java.io.BufferedWriter;
    22→import java.io.IOException;
    23→import java.io.InputStream;
    24→import java.io.InputStreamReader;
    25→import java.io.OutputStream;
    26→import java.io.OutputStreamWriter;
    27→import java.util.Collection;
    28→import java.util.HashSet;
    29→import java.util.Set;
    30→
    31→import com.google.common.io.Closer;
    32→
    33→/**
    34→ * A helper class for reading and writing Services files.
    35→ */
    36→final class ServicesFiles {
    37→  public static final String SERVICES_PATH = "META-INF/services";
    38→
    39→  private ServicesFiles() { }
    40→
    41→  /**
    42→   * Returns an absolute path to a service file given the class
    43→   * name of the service.
    44→   *
    45→   * @param serviceName not {@code null}
    46→   * @return SERVICES_PATH + serviceName
    47→   */
    48→  static String getPath(String serviceName) {
    49→    return SERVICES_PATH + "/" + serviceName;
    50→  }
    51→
    52→  /**
    53→   * Reads the set of service classes from a service file.
    54→   *
    55→   * @param input not {@code null}. Closed after use.
    56→   * @return a not {@code null Set} of service class names.
    57→   * @throws IOException
    58→   */
    59→  static Set<String> readServiceFile(InputStream input) throws IOException {
    60→    HashSet<String> serviceClasses = new HashSet<String>();
    61→    Closer closer = Closer.create();
    62→    try {
    63→      // TODO(gak): use CharStreams
    64→      BufferedReader r = closer.register(new BufferedReader(new InputStreamReader(input, UTF_8)));
    65→      String line;
    66→      while ((line = r.readLine()) != null) {
    67→        int commentStart = line.indexOf('#');
    68→        if (commentStart >= 0) {
    69→          line = line.substring(0, commentStart);
    70→        }
    71→        line = line.trim();
    72→        if (!line.isEmpty()) {
    73→          serviceClasses.add(line);
    74→        }
    75→      }
    76→      return serviceClasses;
    77→    } catch (Throwable t) {
    78→      throw closer.rethrow(t);
    79→    } finally {
    80→      closer.close();
    81→    }
    82→  }
    83→
    84→  /**
    85→   * Writes the set of service class names to a service file.
    86→   *
    87→   * @param output not {@code null}. Not closed after use.
    88→   * @param services a not {@code null Collection} of service class names.
    89→   * @throws IOException
    90→   */
    91→  static void writeServiceFile(Collection<String> services, OutputStream output)
    92→      throws IOException {
    93→    BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(output, UTF_8));
    94→    for (String service : services) {
    95→      writer.write(service);
    96→      writer.newLine();
    97→    }
    98→    writer.flush();
    99→  }
   100→}

