   189→  private static int lastIndexOf(CharSequence charSequence, char c) {
   190→    for (int i = charSequence.length() - 1; i >= 0; i--) {
   191→      if (charSequence.charAt(i) == c) {
   192→        return i;
   193→      }
   194→    }
   195→    return -1;
   196→  }
