    72→      return true;
    73→    } else if (obj instanceof Parameter) {
    74→      Parameter that = (Parameter) obj;
    75→      return this.type.equals(that.type)
    76→          && this.key.equals(that.key)
    77→          && this.name.equals(that.name)
    78→          && this.providerOfType == that.providerOfType;
