   106→  static Parameter forVariableElement(VariableElement variable, TypeMirror type, Types types) {
   107→    ImmutableSet.Builder<AnnotationMirror> qualifiers = ImmutableSet.builder();
   108→    for (AnnotationMirror annotationMirror : variable.getAnnotationMirrors()) {
   109→      DeclaredType annotationType = annotationMirror.getAnnotationType();
   110→      if (isAnnotationPresent(annotationType.asElement(), Qualifier.class)) {
   111→        qualifiers.add(annotationMirror);
   112→      }
   113→    }
   114→
   115→    boolean provider = MoreTypes.isType(type) && MoreTypes.isTypeOf(Provider.class, type);
   116→    TypeMirror providedType =
   117→        provider ? MoreTypes.asDeclared(type).getTypeArguments().get(0) : type;
   118→
   119→    // TODO(gak): check for only one qualifier rather than using the first
   120→    Optional<AnnotationMirror> qualifier = FluentIterable.from(qualifiers.build()).first();
   121→    Key key = new Key(qualifier, boxedType(providedType, types).toString());
   122→
   123→    return new Parameter(
   124→        providedType.toString(), key, variable.getSimpleName().toString(), provider);
   125→  }
   126→
   127→  /**
   128→   * If {@code type} is a primitive type, returns the boxed equivalent; otherwise returns
   129→   * {@code type}.
   130→   */
   131→  private static TypeMirror boxedType(TypeMirror type, Types types) {
   132→    return type.getKind().isPrimitive()
   133→        ? types.boxedClass(MoreTypes.asPrimitiveType(type)).asType()
   134→        : type;
   135→  }
   136→
   137→  static ImmutableSet<Parameter> forParameterList(
   138→      List<? extends VariableElement> variables,
   139→      List<? extends TypeMirror> variableTypes,
   140→      Types types) {
   141→    checkArgument(variables.size() == variableTypes.size());
   142→    ImmutableSet.Builder<Parameter> builder = ImmutableSet.builder();
   143→    Set<String> names = Sets.newHashSetWithExpectedSize(variables.size());
   144→    for (int i = 0; i < variables.size(); i++) {
   145→      Parameter parameter = forVariableElement(variables.get(i), variableTypes.get(i), types);
   146→      checkArgument(names.add(parameter.name));
   147→      builder.add(parameter);
   148→    }
   149→    ImmutableSet<Parameter> parameters = builder.build();
   150→    checkArgument(variables.size() == parameters.size());
   151→    return parameters;
   152→  }
   153→
   154→  static ImmutableSet<Parameter> forParameterList(
   155→      List<? extends VariableElement> variables, Types types) {
   156→    List<TypeMirror> variableTypes = Lists.newArrayListWithExpectedSize(variables.size());
   157→    for (VariableElement var : variables) {
   158→      variableTypes.add(var.asType());
   159→    }
   160→    return forParameterList(variables, variableTypes, types);
   161→  }
   162→}
