    37→
    38→  void checkProvidedParameter(Element element) {
    39→    checkArgument(isAnnotationPresent(element, Provided.class), "%s not annoated with @Provided",
    40→        element);
    41→    element.accept(new ElementKindVisitor6<Void, Void>() {
