    49→        providedParameter.getEnclosingElement().accept(new ElementKindVisitor6<Void, Void>() {
    50→          @Override
    51→          protected Void defaultAction(Element e, Void p) {
    52→            raiseError(providedParameter, "@%s may only be applied to constructor parameters");
    53→            return null;
    54→          }
    55→
    56→          @Override
    57→          public Void visitExecutableAsConstructor(ExecutableElement constructor, Void p) {
    58→            if (!(annotatedWithAutoFactory(constructor)
    59→                || annotatedWithAutoFactory(constructor.getEnclosingElement()))) {
    60→              raiseError(providedParameter,
    61→                  "@%s may only be applied to constructors requesting an auto-factory");
    62→            }
    63→            return null;
    64→          }
    65→        }, p);
    66→        return null;
    67→      }
    68→    }, null);
    69→  }
