    71→  private void raiseError(VariableElement providedParameter, String messageFormat) {
    72→    messager.printMessage(ERROR, String.format(messageFormat, Provided.class.getSimpleName()),
    73→        providedParameter, Mirrors.getAnnotationMirror(providedParameter, Provided.class).get());
