    48→    }
    49→    if (type.getModifiers().contains(FINAL)) {
    50→      return false;
    51→    }
    52→    if (!type.getEnclosingElement().getKind().equals(PACKAGE)
    53→        && !type.getModifiers().contains(STATIC)) {
    54→      return false;
    55→    }
    56→    if (type.getSimpleName().length() == 0) {
    57→      return false;
    58→    }
    59→    return true;
    60→  }
    61→
    62→  /**
    63→   * Given an executable element in a supertype, returns its ExecutableType when it is viewed as a
    64→   * member of a subtype.
    65→   */
    66→  static ExecutableType getExecutableElementAsMemberOf(
    67→      Types types, ExecutableElement executableElement, TypeElement subTypeElement) {
    68→    checkNotNull(types);
    69→    checkNotNull(executableElement);
    70→    checkNotNull(subTypeElement);
    71→    TypeMirror subTypeMirror = subTypeElement.asType();
    72→    if (!subTypeMirror.getKind().equals(TypeKind.DECLARED)) {
    73→      throw new IllegalStateException(
    74→          "Expected subTypeElement.asType() to return a class/interface type.");
    75→    }
    76→    TypeMirror subExecutableTypeMirror = types.asMemberOf(
    77→        (DeclaredType) subTypeMirror, executableElement);
    78→    if (!subExecutableTypeMirror.getKind().equals(TypeKind.EXECUTABLE)) {
    79→      throw new IllegalStateException("Expected subExecutableTypeMirror to be an executable type.");
    80→    }
    81→    return (ExecutableType) subExecutableTypeMirror;
    82→  }
    83→}
